fields.InputDefinition:
{
  "goal": "In the Committees app, open 'Meetings' from the app's navigation (if it is not there, navigate to http://localhost:4200/app/data-explorer/Data?entity=Committees:%20Meetings — do not use the sidebar search, because two entities are called 'Meetings'). Type 'Standards Committee — Q4 2015' in the grid's filter box ('Filter records...') and open the meeting 'Standards Committee — Q4 2015 meeting': click its row and then 'Open Full Record', or double-click the row. Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200/app/mjcommittees",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
